<template>
	<view class="payment-page">
		<view class="cashier-head"><view class="jd-mark">JD</view><view><text>京东收银台</text><text>安全、快捷地完成订单支付</text></view></view>
		<view v-if="loading" class="loading">正在查询支付信息...</view>
		<StateView v-else-if="error" title="支付信息加载失败" :description="error" action-text="重新加载" error @action="loadPayment" />
		<template v-else>
			<view v-if="status.state==='paid'" class="result-panel success"><view class="result-icon">✓</view><text>{{ status.title }}</text><text>{{ status.description }}</text><view class="result-info"><text>订单编号</text><text selectable>{{ orderNo }}</text><text v-if="status.paymentNo">支付单号</text><text v-if="status.paymentNo" selectable>{{ status.paymentNo }}</text></view><button class="primary" @tap="openOrder">查看订单详情</button><button @tap="goHome">返回首页</button></view>
			<view v-else-if="status.state==='processing'" class="result-panel"><view class="result-icon processing">···</view><text>{{ status.title }}</text><text>{{ status.description }}</text><text class="polling">正在自动查询支付结果</text><button class="primary" :loading="refreshing" @tap="refreshStatus">立即查询</button><button @tap="openOrders">稍后查看订单</button></view>
			<template v-else>
				<view class="order-brief"><view><text>订单提交成功，请尽快付款</text><text>订单号：{{ orderNo }}</text></view><view><text>应付金额</text><text>¥{{ formatPrice(amount) }}</text></view></view>
				<view v-if="status.state==='failed'" class="failed-tip">{{ status.description }}</view>
				<view class="method-panel"><view class="panel-head"><view><text>选择支付方式</text><text>当前后端为模拟支付环境</text></view><text>支付安全保障</text></view><view class="method-list"><view v-for="item in methods" :key="item.value" class="method" :class="{selected:payType===item.value}" @tap="payType=item.value"><view class="method-logo" :class="`method-${item.value}`">{{ item.icon }}</view><view><text>{{ item.label }}</text><text>{{ item.description }}</text></view><view class="radio"><text v-if="payType===item.value"></text></view></view></view></view>
				<view class="pay-bar"><view><text>需支付</text><text>¥{{ formatPrice(amount) }}</text></view><button :loading="paying" :disabled="paying" @tap="submitPay">确认支付</button></view>
			</template>
		</template>
	</view>
</template>

<script>
	import StateView from '../../components/StateView.vue'
	import { confirmPayment, createPayment, getOrderDetail, getPaymentStatus } from '../../api/index.js'
	import { formatMoney } from '../../utils/format.js'
	import { extractPaymentNo, normalizeOrderDetail, normalizePaymentStatus } from '../../utils/normalizers.js'
	export default{
		components:{StateView},data(){return{orderNo:'',amount:0,loading:true,error:'',paying:false,refreshing:false,payType:1,status:normalizePaymentStatus(null),pollTimer:null,pollCount:0,methods:[{value:1,label:'微信支付',description:'推荐使用微信支付',icon:'微'},{value:2,label:'支付宝',description:'使用支付宝安全付款',icon:'支'},{value:3,label:'余额支付',description:'使用账户余额付款',icon:'¥'}]}},
		onLoad(options){this.orderNo=String(options.orderNo||'');this.amount=Math.max(0,Number(options.amount||0));this.loadPayment()},onUnload(){this.stopPolling()},
		methods:{formatPrice:formatMoney,async loadPayment(){if(!this.orderNo){this.loading=false;this.error='缺少订单编号';return}this.loading=true;this.error='';const [detailResult,statusResult]=await Promise.allSettled([getOrderDetail(this.orderNo),getPaymentStatus(this.orderNo)]);if(detailResult.status==='fulfilled'){const order=normalizeOrderDetail(detailResult.value);this.amount=order.payAmount;if(order.status!==0)this.status=normalizePaymentStatus(order.payment||{status:[1,2,3].includes(order.status)?1:null})}if(statusResult.status==='fulfilled')this.status=normalizePaymentStatus(statusResult.value);if(detailResult.status==='rejected'&&statusResult.status==='rejected')this.error=detailResult.reason?.message||statusResult.reason?.message||'支付信息加载失败';this.loading=false;if(this.status.state==='processing')this.startPolling()},async refreshStatus(silent=false){if(this.refreshing)return;this.refreshing=!silent;try{let next=normalizePaymentStatus(await getPaymentStatus(this.orderNo));if(this.status.state==='processing'&&next.state==='unpaid')next=this.status;this.status=next;if(next.state==='paid'){this.stopPolling();if(!silent)uni.showToast({title:'支付成功',icon:'success'})}else if(next.state==='processing'&&!silent)this.startPolling()}catch(error){if(!silent)uni.showToast({title:error.message||'查询失败',icon:'none'})}finally{this.refreshing=false}},async submitPay(){if(this.paying)return;this.paying=true;let paymentNo='';try{const created=await createPayment(this.orderNo,this.payType);paymentNo=extractPaymentNo(created);if(!paymentNo){this.status=normalizePaymentStatus({payment:{status:0,payType:this.payType}});this.startPolling();uni.showToast({title:'支付已提交，正在查询结果',icon:'none'});return}this.status=normalizePaymentStatus({payment:{paymentNo,status:0,payType:this.payType}});await confirmPayment(paymentNo);await this.refreshStatus(true);if(this.status.state!=='paid'){this.startPolling();uni.showToast({title:'支付已提交，正在确认',icon:'none'})}else uni.showToast({title:'支付成功',icon:'success'})}catch(error){if(paymentNo){this.status=normalizePaymentStatus({payment:{paymentNo,status:0,payType:this.payType}});this.startPolling();uni.showToast({title:'支付结果暂未确认，正在继续查询',icon:'none'})}else{this.status=normalizePaymentStatus({payment:{status:2,payType:this.payType}});uni.showToast({title:error.message||'支付未完成',icon:'none'})}}finally{this.paying=false}},startPolling(){if(this.pollTimer||this.status.state==='paid')return;this.pollCount=0;const poll=async()=>{this.pollTimer=null;if(this.status.state==='paid'||this.pollCount>=15)return;this.pollCount+=1;await this.refreshStatus(true);if(this.status.state==='processing')this.pollTimer=setTimeout(poll,2000)};this.pollTimer=setTimeout(poll,1800)},stopPolling(){if(this.pollTimer){clearTimeout(this.pollTimer);this.pollTimer=null}},openOrder(){uni.redirectTo({url:`/pages/orders/detail?orderNo=${encodeURIComponent(this.orderNo)}`})},openOrders(){uni.redirectTo({url:'/pages/orders/list'})},goHome(){uni.switchTab({url:'/pages/index/index'})}},
	}
</script>

<style scoped>
	.payment-page{min-height:100vh;padding:18rpx 20rpx 150rpx;background:#f5f6f8}.cashier-head{display:flex;padding:26rpx;align-items:center;border-bottom:4rpx solid #e1251b;background:#fff}.jd-mark{display:flex;width:72rpx;height:72rpx;align-items:center;justify-content:center;border-radius:10rpx;color:#fff;background:#e1251b;font-size:25rpx;font-weight:800}.cashier-head>view:last-child{margin-left:18rpx}.cashier-head text{display:block}.cashier-head text:first-child{color:#2d333a;font-size:30rpx;font-weight:700}.cashier-head text:last-child{margin-top:6rpx;color:#969da6;font-size:20rpx}.loading{display:flex;height:65vh;align-items:center;justify-content:center;color:#969da6;font-size:24rpx}.order-brief{display:flex;margin-top:16rpx;padding:26rpx;align-items:center;justify-content:space-between;border:1rpx solid #eceef1;border-radius:8rpx;background:#fff}.order-brief>view>text{display:block}.order-brief>view:first-child text:first-child{color:#343a42;font-size:26rpx;font-weight:700}.order-brief>view:first-child text:last-child{margin-top:10rpx;color:#8e959f;font-size:20rpx}.order-brief>view:last-child{text-align:right}.order-brief>view:last-child text:first-child{color:#8e959f;font-size:20rpx}.order-brief>view:last-child text:last-child{margin-top:7rpx;color:#e1251b;font-size:36rpx;font-weight:800}.failed-tip{margin-top:14rpx;padding:20rpx;border-left:5rpx solid #e1251b;color:#b23a34;background:#fff0ee;font-size:22rpx}.method-panel{margin-top:16rpx;border:1rpx solid #eceef1;border-radius:8rpx;background:#fff}.panel-head{display:flex;padding:22rpx 24rpx;align-items:center;justify-content:space-between;border-bottom:1rpx solid #eef0f2}.panel-head>view text{display:block}.panel-head>view text:first-child{color:#343a42;font-size:27rpx;font-weight:700}.panel-head>view text:last-child{margin-top:6rpx;color:#9ba1a9;font-size:19rpx}.panel-head>text{color:#58a13b;font-size:20rpx}.method-list{padding:18rpx}.method{display:grid;grid-template-columns:76rpx minmax(0,1fr) 38rpx;min-height:112rpx;margin-top:12rpx;padding:16rpx;align-items:center;gap:16rpx;border:1rpx solid #dfe2e6;border-radius:8rpx}.method:first-child{margin-top:0}.method.selected{border:2rpx solid #e1251b;padding:15rpx;background:#fffafa}.method-logo{display:flex;width:68rpx;height:68rpx;align-items:center;justify-content:center;border-radius:10rpx;color:#fff;font-size:28rpx;font-weight:800}.method-1{background:#20b663}.method-2{background:#1677ff}.method-3{background:#e1251b}.method>view:nth-child(2) text{display:block}.method>view:nth-child(2) text:first-child{color:#343a42;font-size:25rpx;font-weight:700}.method>view:nth-child(2) text:last-child{margin-top:7rpx;color:#969da6;font-size:20rpx}.radio{display:flex;width:34rpx;height:34rpx;align-items:center;justify-content:center;border:2rpx solid #cfd3d8;border-radius:50%}.method.selected .radio{border-color:#e1251b}.radio text{width:17rpx;height:17rpx;border-radius:50%;background:#e1251b}.pay-bar{position:fixed;right:0;bottom:0;left:0;z-index:10;display:flex;min-height:108rpx;padding:14rpx 22rpx calc(14rpx + env(safe-area-inset-bottom));align-items:center;border-top:1rpx solid #e2e5e8;background:#fff}.pay-bar>view{min-width:0;flex:1}.pay-bar>view text{display:block;color:#8d949e;font-size:19rpx}.pay-bar>view text:last-child{margin-top:5rpx;color:#e1251b;font-size:31rpx;font-weight:800}.pay-bar button{width:220rpx;height:76rpx;margin:0;border:0;border-radius:8rpx;color:#fff;background:#e1251b;font-size:25rpx;line-height:76rpx}.result-panel{display:flex;min-height:620rpx;margin-top:16rpx;padding:48rpx 28rpx;align-items:center;flex-direction:column;border:1rpx solid #eceef1;border-radius:8rpx;background:#fff;text-align:center}.result-icon{display:flex;width:120rpx;height:120rpx;align-items:center;justify-content:center;border-radius:50%;color:#e1251b;background:#fff0ee;font-size:50rpx;font-weight:800}.result-panel.success .result-icon{color:#fff;background:#55a63c}.result-panel>text:nth-child(2){margin-top:24rpx;color:#292f36;font-size:36rpx;font-weight:800}.result-panel>text:nth-child(3){margin-top:12rpx;color:#858d97;font-size:23rpx;line-height:1.6}.result-info{display:grid;grid-template-columns:120rpx minmax(0,1fr);width:100%;margin:30rpx 0 12rpx;padding:22rpx;gap:14rpx;background:#fafbfc;color:#9299a3;font-size:21rpx;text-align:left}.result-info text:nth-child(even){color:#4d555f;overflow-wrap:anywhere}.result-panel button{width:100%;height:74rpx;margin:14rpx 0 0;border:1rpx solid #d9dde2;border-radius:7rpx;color:#59616b;background:#fff;font-size:23rpx;line-height:74rpx}.result-panel button.primary{color:#fff;border-color:#e1251b;background:#e1251b}.polling{color:#e1251b!important}.processing{font-size:34rpx}
</style>
